INSERT INTO dump_descriptions (base_key, description) VALUES ('whiteasylum', 'Turns selected biome environment material tints white across Azure Weald, Hollow Bough, Bone Yards, Fungus Bogs, and other regions.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('minimalism', 'Cuts cave-scene clutter by stripping emitters from many particle effects and removing or simplifying selected props, meshes, and materials.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('dea_a05t1', 'Adds custom enemy variants including Glasher, Guardian, Clubber, colored Spitters, new Shooters, Mactera, Grooters, Fanatics, and Shooting Plants.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('dea_a05t2', 'Adds custom enemy variants including Glasher, Guardian, Clubber, colored Spitters, new Shooters, Mactera, Grooters, Fanatics, and Shooting Plants.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('doa', 'Adds 30 custom overclock upgrades and schematics for weapons and equipment, including Advanced Combat Module, Barrier System, Cryo Nade Launcher, and Tuned Platform.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('woh', 'Adds War of Hoxxes enemy variants and themed mission warning content, including Golems, Sharks, Assault Bots, Ghosts, Tendrils, and Fortress, Graveyard, and Tomb warnings.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('nea_tendril_fix_v0.4.7_base', 'Includes War of Hoxxes enemies and warning content, including Tendril and Golem variants, and updates the spider enemy registry to include its custom entries.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
